added = set(git(root, "diff", "--name-only", "--diff-filter=A", base + "...HEAD", "--", *files).split())
changed = [f for f in files if f not in added]
if changed:
    parts.append("### Diff against %s\n\n%s\n" % (base, fence(git(root, "diff", base + "...HEAD", "--", *changed))))
for name in files:
    path = root / name
    body = path.read_text(errors="replace") if path.exists() else "(deleted)"
    label = name + " (new file)" if name in added else name
    parts.append("### %s\n\n%s\n" % (label, fence(body)))
return "\n".join(parts)

